using System;
using Rhino.Geometry;

namespace BenchPlugin.Facade
{
    /// <summary>One four-sided facade panel cut from a surface.</summary>
    public class Panel
    {
        public Panel(Point3d c0, Point3d c1, Point3d c2, Point3d c3, int index)
        {
            Corners = new[] { c0, c1, c2, c3 };
            Index = index;
            Area = 0.5 * Vector3d.CrossProduct(c2 - c0, c3 - c1).Length;
            Deviation = ComputeDeviation(c0, c1, c2, c3);
        }

        /// <summary>Four corners in order around the panel.</summary>
        public Point3d[] Corners { get; }
        public int Index { get; }
        public double Area { get; }
        /// <summary>Distance from the fourth corner to the plane through the other three.</summary>
        public double Deviation { get; }

        public Point3d Center =>
            new Point3d(
                (Corners[0].X + Corners[1].X + Corners[2].X + Corners[3].X) / 4.0,
                (Corners[0].Y + Corners[1].Y + Corners[2].Y + Corners[3].Y) / 4.0,
                (Corners[0].Z + Corners[1].Z + Corners[2].Z + Corners[3].Z) / 4.0);

        /// <summary>Closed outline curve.</summary>
        public PolylineCurve Outline =>
            new PolylineCurve(new[] { Corners[0], Corners[1], Corners[2], Corners[3], Corners[0] });

        /// <summary>Length of edge i (0: c0-c1, 1: c1-c2, 2: c2-c3, 3: c3-c0).</summary>
        public double EdgeLength(int i) => Corners[i].DistanceTo(Corners[(i + 1) % 4]);

        /// <summary>Mean of the first and third edge lengths.</summary>
        public double Width => (EdgeLength(0) + EdgeLength(2)) / 2.0;

        /// <summary>Mean of the second and fourth edge lengths.</summary>
        public double Height => (EdgeLength(1) + EdgeLength(3)) / 2.0;

        /// <summary>Four edge lengths sorted ascending.</summary>
        public double[] SortedEdges()
        {
            var e = new[] { EdgeLength(0), EdgeLength(1), EdgeLength(2), EdgeLength(3) };
            Array.Sort(e);
            return e;
        }

        /// <summary>Two diagonal lengths sorted ascending.</summary>
        public double[] SortedDiagonals()
        {
            var d = new[] { Corners[0].DistanceTo(Corners[2]), Corners[1].DistanceTo(Corners[3]) };
            Array.Sort(d);
            return d;
        }

        private static double ComputeDeviation(Point3d a, Point3d b, Point3d c, Point3d d)
        {
            Vector3d n = Vector3d.CrossProduct(b - a, c - a);
            double len = n.Length;
            if (len > 1e-12)
                return Math.Abs((d - a) * n) / len;
            // Degenerate (collinear) first three corners: fall back to distance from the line.
            var line = new Line(a, c.DistanceTo(a) > 1e-12 ? c : b);
            return line.DistanceTo(d, false);
        }
    }
}

