using System;
using System.Collections.Generic;
using Grasshopper.Kernel;
using Grasshopper.Kernel.Types;

namespace BenchPlugin.Facade
{
    /// <summary>Grasshopper wrapper so a Panel travels as one value on its own wire.</summary>
    public class GH_Panel : GH_Goo<Panel>
    {
        public GH_Panel() { }
        public GH_Panel(Panel panel) : base(panel) { }
        public GH_Panel(GH_Panel other) : base(other.Value) { }

        public override bool IsValid => Value != null;
        public override string TypeName => "Panel";
        public override string TypeDescription => "Four-sided facade panel";
        public override IGH_Goo Duplicate() => new GH_Panel(Value);

        public override string ToString() =>
            Value == null ? "Null Panel" : $"Panel {Value.Index} (area {Value.Area:0.###})";

        public override bool CastFrom(object source)
        {
            if (source is Panel p) { Value = p; return true; }
            if (source is GH_Panel g) { Value = g.Value; return true; }
            return false;
        }
    }

    public class PanelParam : GH_Param<GH_Panel>
    {
        public PanelParam()
            : base("Panel", "P", "Facade panel", "Facade", "Params", GH_ParamAccess.item)
        {
        }

        public override Guid ComponentGuid => new Guid("b7e1c2a0-5d34-4f6a-9b18-2a4c6e8d0f11");
        public override GH_Exposure Exposure => GH_Exposure.hidden;
    }

    internal static class PanelIO
    {
        /// <summary>Reads all panels from an input; null entries are dropped. False if nothing was supplied.</summary>
        public static bool GetPanels(IGH_DataAccess da, int index, out List<Panel> panels)
        {
            panels = new List<Panel>();
            var goos = new List<GH_Panel>();
            if (!da.GetDataList(index, goos)) return false;
            foreach (var g in goos)
                if (g != null && g.Value != null) panels.Add(g.Value);
            return panels.Count > 0;
        }
    }
}

