using System;
using System.Collections.Generic;
using Grasshopper.Kernel;
using Rhino.Geometry;

namespace BenchPlugin.Facade
{
    public class PanelizeSurfaceComponent : GH_Component
    {
        public PanelizeSurfaceComponent()
            : base("Panelize Surface", "Panelize", "Divide a surface into a grid of four-sided panels", "Facade", "Panels")
        {
        }

        public override Guid ComponentGuid => new Guid("c1a10001-2b3c-4d5e-8f60-71829304a5b6");

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            pManager.AddSurfaceParameter("Surface", "S", "Surface to panelize", GH_ParamAccess.item);
            pManager.AddIntegerParameter("U Count", "U", "Panels in the U direction", GH_ParamAccess.item, 10);
            pManager.AddIntegerParameter("V Count", "V", "Panels in the V direction", GH_ParamAccess.item, 6);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddParameter(new PanelParam(), "Panels", "P", "Panels (index = u * V Count + v)", GH_ParamAccess.list);
            pManager.AddCurveParameter("Outlines", "O", "Closed panel outlines", GH_ParamAccess.list);
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            Surface surface = null;
            int uCount = 10, vCount = 6;
            if (!DA.GetData(0, ref surface) || surface == null) return;
            if (!DA.GetData(1, ref uCount)) return;
            if (!DA.GetData(2, ref vCount)) return;

            if (uCount < 1 || vCount < 1)
            {
                AddRuntimeMessage(GH_RuntimeMessageLevel.Error, "U Count and V Count must be at least 1.");
                return;
            }

            Interval du = surface.Domain(0), dv = surface.Domain(1);
            var pts = new Point3d[uCount + 1, vCount + 1];
            for (int i = 0; i <= uCount; i++)
                for (int j = 0; j <= vCount; j++)
                    pts[i, j] = surface.PointAt(du.ParameterAt((double)i / uCount), dv.ParameterAt((double)j / vCount));

            var panels = new List<GH_Panel>(uCount * vCount);
            var outlines = new List<Curve>(uCount * vCount);
            for (int i = 0; i < uCount; i++)
                for (int j = 0; j < vCount; j++)
                {
                    var p = new Panel(pts[i, j], pts[i + 1, j], pts[i + 1, j + 1], pts[i, j + 1], i * vCount + j);
                    panels.Add(new GH_Panel(p));
                    outlines.Add(p.Outline);
                }

            DA.SetDataList(0, panels);
            DA.SetDataList(1, outlines);
        }
    }

    public class PanelInfoComponent : GH_Component
    {
        public PanelInfoComponent()
            : base("Panel Info", "PanelInfo", "Properties of a single panel", "Facade", "Panels")
        {
        }

        public override Guid ComponentGuid => new Guid("c1a10002-2b3c-4d5e-8f60-71829304a5b6");

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            pManager.AddParameter(new PanelParam(), "Panel", "P", "Panel", GH_ParamAccess.item);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddPointParameter("Corners", "C", "Four corners in order around the panel", GH_ParamAccess.list);
            pManager.AddCurveParameter("Outline", "O", "Closed outline", GH_ParamAccess.item);
            pManager.AddNumberParameter("Area", "A", "Panel area", GH_ParamAccess.item);
            pManager.AddPointParameter("Center", "Ce", "Average of the four corners", GH_ParamAccess.item);
            pManager.AddIntegerParameter("Index", "I", "Index in the grid", GH_ParamAccess.item);
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            GH_Panel goo = null;
            if (!DA.GetData(0, ref goo) || goo == null || goo.Value == null) return;
            Panel p = goo.Value;
            DA.SetDataList(0, p.Corners);
            DA.SetData(1, p.Outline);
            DA.SetData(2, p.Area);
            DA.SetData(3, p.Center);
            DA.SetData(4, p.Index);
        }
    }
}

