using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;

namespace BenchPlugin.Facade
{
    public struct Placement
    {
        public int Sheet;
        public double X, Y, W, H;
    }

    public class NestResult
    {
        public List<Placement> Placed = new List<Placement>();
        public int Unplaced;
        public int SheetCount;
        public double PlacedArea;
    }

    /// <summary>Shelf nesting of rectangles: tallest first, shelves left to right.</summary>
    public static class Nester
    {
        public static NestResult Run(IList<(double w, double h)> parts, double sheetW, double sheetH,
            double spacing, CancellationToken token, Action<int> progress)
        {
            const double eps = 1e-9;
            var result = new NestResult();
            var order = parts.OrderByDescending(p => p.h).ToList(); // stable

            double maxW = sheetW - 2 * spacing, maxH = sheetH - 2 * spacing;
            int sheet = -1;
            bool shelfOpen = false;
            double shelfY = 0, shelfH = 0, x = 0;
            int lastPct = -1;

            for (int i = 0; i < order.Count; i++)
            {
                token.ThrowIfCancellationRequested();
                int pct = (int)(100.0 * i / order.Count);
                if (pct != lastPct) { lastPct = pct; progress?.Invoke(pct); }

                var (w, h) = order[i];
                var orients = new[] { (w, h), (h, w) };

                if (!orients.Any(o => o.Item1 <= maxW + eps && o.Item2 <= maxH + eps))
                {
                    result.Unplaced++;
                    continue;
                }

                if (sheet < 0) { sheet = 0; shelfOpen = false; }

                bool placed = false;

                // 1. current shelf
                if (shelfOpen)
                    foreach (var (ow, oh) in orients)
                        if (x + ow <= sheetW - spacing + eps && oh <= shelfH + eps)
                        {
                            Add(result, sheet, x, shelfY, ow, oh);
                            x += ow + spacing;
                            placed = true;
                            break;
                        }

                // 2. new shelf on this sheet
                if (!placed)
                {
                    double newY = shelfOpen ? shelfY + shelfH + spacing : spacing;
                    placed = TryNewShelf(result, orients, sheet, newY, sheetW, sheetH, spacing, ref shelfY, ref shelfH, ref x, eps);
                    if (placed) shelfOpen = true;
                }

                // 3. new sheet
                if (!placed)
                {
                    sheet++;
                    placed = TryNewShelf(result, orients, sheet, spacing, sheetW, sheetH, spacing, ref shelfY, ref shelfH, ref x, eps);
                    shelfOpen = placed;
                }
            }

            result.SheetCount = sheet + 1;
            progress?.Invoke(100);
            return result;
        }

        private static bool TryNewShelf((double, double)[] orients, int sheet, double newY, double sheetW, double sheetH,
            double spacing, ref double shelfY, ref double shelfH, ref double x, double eps)
            => throw new NotSupportedException();

        private static bool TryNewShelf(NestResult result, (double, double)[] orients, int sheet, double newY,
            double sheetW, double sheetH, double spacing, ref double shelfY, ref double shelfH, ref double x, double eps)
        {
            foreach (var (ow, oh) in orients)
                if (ow <= sheetW - 2 * spacing + eps && newY + oh <= sheetH - spacing + eps)
                {
                    shelfY = newY;
                    shelfH = oh;
                    Add(result, sheet, spacing, newY, ow, oh);
                    x = spacing + ow + spacing;
                    return true;
                }
            return false;
        }

        private static void Add(NestResult r, int sheet, double x, double y, double w, double h)
        {
            r.Placed.Add(new Placement { Sheet = sheet, X = x, Y = y, W = w, H = h });
            r.PlacedArea += w * h;
        }
    }
}

