                    x = spacing + ow + spacing;
                    return true;
                }
            return false;
        }

        private static void Add(NestResult r, int sheet, double x, double y, double w, double h)
        {
            r.Placed.Add(new Placement { Sheet = sheet, X = x, Y = y, W = w, H = h });
            r.PlacedArea += w * h;
        }
    }
}

