using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using Grasshopper.Kernel;
using Rhino.Geometry;

namespace BenchPlugin.Facade
{
    public class GroupIdenticalPanelsComponent : GH_Component
    {
        public GroupIdenticalPanelsComponent()
            : base("Group Identical Panels", "Group", "Group panels with matching edge and diagonal lengths", "Facade", "Fabrication")
        {
        }

        public override Guid ComponentGuid => new Guid("c1a10006-2b3c-4d5e-8f60-71829304a5b6");

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            pManager.AddParameter(new PanelParam(), "Panels", "P", "Panels", GH_ParamAccess.list);
            pManager.AddNumberParameter("Tolerance", "T", "Maximum length difference", GH_ParamAccess.item, 1.0);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddIntegerParameter("Group", "G", "Group number per panel", GH_ParamAccess.list);
            pManager.AddIntegerParameter("Group Count", "N", "Number of groups", GH_ParamAccess.item);
            pManager.AddParameter(new PanelParam(), "Representatives", "R", "First panel of each group", GH_ParamAccess.list);
        }

        private static bool Similar(double[] a, double[] b, double tol)
        {
            for (int i = 0; i < a.Length; i++)
                if (Math.Abs(a[i] - b[i]) > tol) return false;
            return true;
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            if (!PanelIO.GetPanels(DA, 0, out var panels)) return;
            double tol = 1.0;
            if (!DA.GetData(1, ref tol)) return;

            var reps = new List<Panel>();
            var repEdges = new List<double[]>();
            var repDiags = new List<double[]>();
            var groups = new List<int>(panels.Count);

            foreach (var p in panels)
            {
                var e = p.SortedEdges();
                var d = p.SortedDiagonals();
                int g = -1;
                for (int k = 0; k < reps.Count; k++)
                    if (Similar(e, repEdges[k], tol) && Similar(d, repDiags[k], tol)) { g = k; break; }
                if (g < 0)
                {
                    g = reps.Count;
                    reps.Add(p);
                    repEdges.Add(e);
                    repDiags.Add(d);
                }
                groups.Add(g);
            }

            DA.SetDataList(0, groups);
            DA.SetData(1, reps.Count);
            DA.SetDataList(2, reps.Select(r => new GH_Panel(r)));
        }
    }

    public class NestOnSheetsComponent : GH_Component
    {
        private CancellationTokenSource _cts;
        private long _runKey;
        private bool _running;
        private long _resultKey;
        private NestResult _result;
        private string _error;
        private double _sheetW, _sheetH;

        public NestOnSheetsComponent()
            : base("Nest On Sheets", "Nest", "Nest panels as rectangles on sheets using a shelf algorithm", "Facade", "Fabrication")
        {
        }

        public override Guid ComponentGuid => new Guid("c1a10007-2b3c-4d5e-8f60-71829304a5b6");

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            pManager.AddParameter(new PanelParam(), "Panels", "P", "Panels", GH_ParamAccess.list);
            pManager.AddNumberParameter("Sheet Width", "W", "Sheet width", GH_ParamAccess.item, 3000.0);
            pManager.AddNumberParameter("Sheet Height", "H", "Sheet height", GH_ParamAccess.item, 1500.0);
            pManager.AddNumberParameter("Spacing", "S", "Gap between parts and from the sheet edge", GH_ParamAccess.item, 10.0);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddCurveParameter("Outlines", "O", "Placed rectangles; sheets are laid out along X", GH_ParamAccess.list);
            pManager.AddIntegerParameter("Sheet", "S", "Sheet index of each placed panel", GH_ParamAccess.list);
            pManager.AddIntegerParameter("Sheet Count", "N", "Number of sheets used", GH_ParamAccess.item);
            pManager.AddNumberParameter("Utilization", "U", "Placed area / total sheet area", GH_ParamAccess.item);
        }

        private void Cancel()
        {
            var c = _cts;
            _cts = null;
            _running = false;
            if (c != null) { c.Cancel(); }
        }

        public override void RemovedFromDocument(GH_Document document)
        {
            Cancel();
            base.RemovedFromDocument(document);
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            double w = 3000, h = 1500, s = 10;
            if (!PanelIO.GetPanels(DA, 0, out var panels))
            {
                Cancel();
                _result = null;
                Message = null;
                return;
            }
            if (!DA.GetData(1, ref w) || !DA.GetData(2, ref h) || !DA.GetData(3, ref s)) return;

            if (w <= 0 || h <= 0 || s < 0)
            {
                Cancel();
                Message = null;
                AddRuntimeMessage(GH_RuntimeMessageLevel.Error, "Sheet size must be positive and Spacing cannot be negative.");
                return;
            }

            var hc = new HashCode();
            hc.Add(w); hc.Add(h); hc.Add(s);
            foreach (var p in panels)
                foreach (var c in p.Corners) { hc.Add(c.X); hc.Add(c.Y); hc.Add(c.Z); }
            long key = hc.ToHashCode();

            if (_result != null && _resultKey == key)
            {
                Message = null;
                Output(DA);
                return;
            }

            if (_error != null && _resultKey == key)
            {
                Message = null;
                AddRuntimeMessage(GH_RuntimeMessageLevel.Error, _error);
                return;
            }

            if (_running && _runKey == key)
            {
                // Same inputs, still computing: keep waiting.
                return;
            }

            // Inputs changed: stop the old run and start a new one.
            Cancel();
            _result = null;
            _error = null;
            _runKey = key;
            _sheetW = w;
            _sheetH = h;
            _running = true;
            Message = "Nesting 0%";

            var cts = new CancellationTokenSource();
            _cts = cts;
            var token = cts.Token;
            var parts = panels.Select(p => (p.Width, p.Height)).ToList();
            int lastShown = 0;

            Task.Run(() =>
            {
                NestResult res = null;
                string err = null;
                try
                {
                    res = Nester.Run(parts, w, h, s, token, pct =>
                    {
                        if (pct == lastShown) return;
                        lastShown = pct;
                        Rhino.RhinoApp.InvokeOnUiThread(new Action(() =>
                        {
                            if (_cts != cts) return;
                            Message = $"Nesting {pct}%";
                            OnDisplayExpired(false);
                        }));
                    });
                }
                catch (OperationCanceledException) { return; }
                catch (Exception ex) { err = ex.Message; }

                if (token.IsCancellationRequested) return;
                Rhino.RhinoApp.InvokeOnUiThread(new Action(() =>
                {
                    if (_cts != cts) return;
                    _running = false;
                    _result = res;
                    _error = err;
                    _resultKey = key;
                    ExpireSolution(true);
                }));
            }, token);
        }

        private void Output(IGH_DataAccess DA)
        {
            var r = _result;
            if (r.Unplaced > 0)
                AddRuntimeMessage(GH_RuntimeMessageLevel.Warning,
                    $"{r.Unplaced} panel(s) do not fit on any sheet.");

            var outlines = new List<Curve>(r.Placed.Count);
            var sheets = new List<int>(r.Placed.Count);
            foreach (var p in r.Placed)
            {
                double ox = p.Sheet * (_sheetW + 100.0) + p.X;
                outlines.Add(new PolylineCurve(new[]
                {
                    new Point3d(ox, p.Y, 0), new Point3d(ox + p.W, p.Y, 0),
                    new Point3d(ox + p.W, p.Y + p.H, 0), new Point3d(ox, p.Y + p.H, 0),
                    new Point3d(ox, p.Y, 0)
                }));
                sheets.Add(p.Sheet);
            }

            double util = r.SheetCount > 0 ? r.PlacedArea / (r.SheetCount * _sheetW * _sheetH) : 0.0;
            DA.SetDataList(0, outlines);
            DA.SetDataList(1, sheets);
            DA.SetData(2, r.SheetCount);
            DA.SetData(3, util);
        }
    }

    public class CutListComponent : GH_Component
    {
        public CutListComponent()
            : base("Cut List", "CutList", "CSV cut list of panel sizes, optionally written to a file", "Facade", "Fabrication")
        {
        }

        public override Guid ComponentGuid => new Guid("c1a10008-2b3c-4d5e-8f60-71829304a5b6");

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            pManager.AddParameter(new PanelParam(), "Panels", "P", "Panels", GH_ParamAccess.list);
            pManager.AddTextParameter("Path", "Path", "CSV file path", GH_ParamAccess.item, "");
            pManager.AddBooleanParameter("Write", "W", "Write the CSV to Path", GH_ParamAccess.item, false);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddTextParameter("CSV", "CSV", "Cut list as CSV text", GH_ParamAccess.item);
            pManager.AddBooleanParameter("Written", "W", "True when the file was written", GH_ParamAccess.item);
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            if (!PanelIO.GetPanels(DA, 0, out var panels)) return;
            string path = "";
            bool write = false;
            DA.GetData(1, ref path);
            DA.GetData(2, ref write);

            var inv = CultureInfo.InvariantCulture;
            var sb = new StringBuilder();
            sb.AppendLine("index,width,height,area,deviation");
            foreach (var p in panels)
                sb.AppendLine(string.Join(",",
                    p.Index.ToString(inv), p.Width.ToString("0.###", inv), p.Height.ToString("0.###", inv),
                    p.Area.ToString("0.###", inv), p.Deviation.ToString("0.###", inv)));
            string csv = sb.ToString();

            bool written = false;
            if (write)
            {
                if (string.IsNullOrWhiteSpace(path))
                    AddRuntimeMessage(GH_RuntimeMessageLevel.Error, "Write is true but Path is empty.");
                else
                {
                    try
                    {
                        File.WriteAllText(path, csv);
                        written = true;
                    }
                    catch (Exception ex)
                    {
                        AddRuntimeMessage(GH_RuntimeMessageLevel.Error, "Could not write file: " + ex.Message);
                    }
                }
            }

            DA.SetData(0, csv);
            DA.SetData(1, written);
        }
    }
}

